<script setup lang="ts">
import { computed, ref } from 'vue';
import { project, projectId, resources, saveProject, deleteProject, switchProject, sync, flush } from '../platform';
import { data, toast, ask } from '../store';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import EnvironmentPicker from '../components/EnvironmentPicker.vue';
const editing=ref<{id?:string;name:string;code:string;description:string;baseUrl:string}>(), migrating=ref(false), busy=ref(false), error=ref('');
const projectEnvs=computed(()=>resources.value.environments.filter(e=>e.siteId===projectId.value));
function edit(row?:any) { editing.value={id:row?.id,name:row?.name||'',code:row?.code||'',description:row?.description||row?.scope||'',baseUrl:row?.baseUrl||'http://127.0.0.1:8080'}; migrating.value=false; error.value=''; }
async function save() { busy.value=true; error.value=''; try { await saveProject(editing.value!,migrating.value); editing.value=undefined; toast('项目已保存到数据库'); } catch(e) { error.value=(e as Error).message; } finally {busy.value=false;} }
async function choose(id:string) { try {await switchProject(id); toast('已切换项目');}catch(e){toast((e as Error).message,true);} }
async function remove(row:any) { if(!await ask(`删除项目“${row.name}”及其环境和测试配置？此操作不可撤销。`))return; try {await deleteProject(row.id);toast('项目已删除');}catch(e){toast((e as Error).message,true);} }
function counts(id:string) {const d=resources.value.executionSpaces.find(s=>s.siteId===id)?.data;return (d?.requests?.length||0)+(d?.uiCases?.length||0);}
</script>
<template><div class="page config-page"><div class="page-heading"><div><div class="eyebrow">CONTEXT BEFORE EXECUTION</div><h1>项目与环境</h1><p>把被测系统、环境变量和测试资产放在同一个上下文里。</p></div><button class="button primary" @click="edit()"><Icon name="plus" />新建项目</button></div>
  <div class="config-overview"><div><span class="muted">当前项目</span><h2>{{project?.name||'尚未创建项目'}}</h2></div><div><strong>{{resources.sites.length}}</strong><span>个项目</span></div><div><strong>{{projectEnvs.length}}</strong><span>套环境</span></div><span class="badge soft">数据库共享</span></div>
  <div v-if="!resources.sites.length" class="card config-empty"><Icon name="projects" :size="35" /><h2>从一个被测系统开始</h2><p>创建项目后，即可配置环境并执行六类测试。</p><button class="button primary" @click="edit()">创建首个项目</button></div>
  <div v-else class="project-list"><article v-for="row in resources.sites" :key="row.id" class="card project-item" :class="{selected:row.id===projectId}"><div class="project-icon"><Icon name="projects" :size="24" /></div><div class="project-detail"><div class="section-title"><h2>{{row.name}}</h2><span v-if="row.id===projectId" class="badge soft">当前项目</span><span v-else class="project-code">{{row.code||'PROJECT'}}</span></div><p class="muted">{{row.description||row.scope||'暂无项目说明'}}</p><code>{{row.baseUrl}}</code><div class="project-meta"><span>{{resources.environments.filter(e=>e.siteId===row.id).length}} 套环境</span><span>{{counts(row.id)}} 条接口 / UI 用例</span><span>版本 {{row.revision}}</span></div></div><div class="project-actions"><button v-if="row.id!==projectId" class="button small" @click="choose(row.id)">切换项目</button><button class="button small" @click="edit(row)">编辑</button><button class="icon-button" :aria-label="`删除项目 ${row.name}`" @click="remove(row)"><Icon name="trash" /></button></div></article></div>
  <section v-if="project" class="card config-panel environment-panel"><div class="section-title"><div><h2>环境与变量</h2><p class="muted help">当前项目 · {{project.name}}。修改后自动同步到数据库。</p></div><EnvironmentPicker /></div><div class="env-variable-grid"><article v-for="row in data.environments" :key="row.id" class="env-summary"><h3>{{row.name}} <span v-if="row.id===data.environmentId" class="badge soft">执行环境</span></h3><dl><template v-for="v in row.variables.filter(v=>v.enabled&&v.key)" :key="v.id"><dt>{{v.key}}</dt><dd>{{/token|secret|password|key/i.test(v.key)?'••••••••':v.value||'空值'}}</dd></template></dl></article></div><div v-if="sync.error" class="error-banner">{{sync.error}} <button class="text-button" @click="flush">重试保存</button></div></section>
  <Modal v-if="editing" :title="editing.id?'编辑项目':'新建项目'" @close="editing=undefined"><form id="project-form" @submit.prevent="save"><label class="field">项目名称<input v-model="editing.name" required maxlength="200" aria-label="项目名称" /></label><div class="two-fields"><label class="field">项目标识<input v-model="editing.code" maxlength="30" placeholder="例如 TESTPILOT" /></label><label class="field">默认地址<input v-model="editing.baseUrl" required type="url" aria-label="项目默认地址" /></label></div><label class="field">项目说明<textarea v-model="editing.description" maxlength="2000" /></label><label v-if="!editing.id&&!resources.sites.length" class="checkbox-label"><input v-model="migrating" type="checkbox" />将当前浏览器已有用例与测试配置导入此项目</label><div v-if="error" class="error-banner" role="alert">{{error}}</div></form><template #footer><button class="button" @click="editing=undefined">取消</button><button form="project-form" class="button primary" :disabled="busy">{{busy?'保存中…':'保存项目'}}</button></template></Modal>
</div></template>
